internal static TValue cos_pi_decimal_ieee754<TDecimal, TValue>(TValue x)
    where TDecimal : unmanaged, IDecimalIeee754ParseAndFormatInfo<TDecimal, TValue>
    where TValue : unmanaged, IBinaryInteger<TValue>
{
