    }

    Debug.Assert(b <= 63, "Invalid label length byte");
    int labelLen = b;
    _pos++;
    Debug.Assert(_pos + labelLen <= _buffer.Length, "Label extends past buffer");
    _current = _buffer.Slice(_pos, labelLen);
    _pos += labelLen;
    return true;
}
