            UpdateKeys(ref key0, ref key1, ref key2, passwordBytes[i]);
        }
    }
    finally
    {
        ClearSensitiveData(passwordBytes);
        ArrayPool<byte>.Shared.Return(passwordBytes);
    }

    return new ZipCryptoKeys(key0, key1, key2);
}
